  for(let retry=0;retry<5;retry++){const stored=await bucket.get(key),previous=stored?await stored.json():{count:0};const count=Array.isArray(previous)?previous.length:previous.count;if(count>=5)throw new Error('Hosted daily AI limit reached (5 attempts). Source outlines remain available.');const condition=stored?{etagMatches:stored.etag}:{etagDoesNotMatch:'*'};if(await write(bucket,key,{count:count+1,last_attempt:new Date().toISOString()},{onlyIf:condition})){reserved=true;break}}
