  const normalizations=[];const daySource=/\bday\s*1\b/i.exec(job.description);if(daySource){for(const field of ['cover_letter','cold_email_subject','cold_email','cv_summary'])if(typeof generated[field]==='string')generated[field]=generated[field].replace(/\bday\s*1\b/gi,from=>{normalizations.push({field,from,to:'first day',source_quote:daySource[0],source_url:job.original_application_url||job.url});return 'first day'});}
