function draftNumbers(text){return new Set((String(text).match(/\b\d+(?:,\d{3})*(?:\.\d+)?%?/g)||[]).map(n=>String(Number(n.replace(/,/g,'').replace(/%$/,'')))+(n.endsWith('%')?'%':'')))}
