      if(user&&!await owner(bucket,user))return reply({error:'Owner access required'},403);
      if(path==='/api/bridge/email-receipt'&&req.method==='POST'){if(user||req.headers.has('Origin'))return reply({error:'External receipt imports require owner service access'},403);return reply(await importEmailReceipt(bucket,await jsonBody(req)))}
