      if(path==='/api/bridge/editorial-revision'&&req.method==='POST'){const body=await jsonBody(req);return reply(await editorialRevision(env,body))}
      if(path==='/api/bridge/recover-draft'&&req.method==='POST'){const body=await jsonBody(req);return reply(await recoverDraft(env,body.failure_id))}
      if(path==='/api/bridge/package'&&req.method==='POST'){const body=await jsonBody(req);if(typeof body.job_id!=='string'||body.job_id.length>250)throw new Error('Job identity required');return reply(await hostedPackage(env,body.job_id,body.use_ai!==false))}
      if(path==='/api/bridge/discover'&&req.method==='POST'){const body=await jsonBody(req);return reply(await hostedDiscover(env,{idempotency_key:body.idempotency_key}))}
